// Match by title substring
function findQuestions(title) {
  for (const [key, questions] of Object.entries(questionBanks)) {
    if (title.toLowerCase().includes(key.toLowerCase()) || key.toLowerCase().includes(title.toLowerCase().substring(0, 20))) {
      return questions
    }
  }
  // Generic fallback
  return null
}

async function run() {
  const { data: courses, error } = await supabase.from('courses').select('id, title')
  if (error) { console.error('Failed to fetch courses:', error.message); process.exit(1) }
  console.log(`Seeding question banks for ${courses.length} courses...`)

  let matched = 0, unmatched = []
  for (const course of courses) {
    const questions = findQuestions(course.title)
    if (!questions) {
      unmatched.push(course.title)
      continue
    }
    const { error: updateError } = await supabase.from('courses').update({ question_bank: questions }).eq('id', course.id)
    if (updateError) {
      console.log(`✗ ${course.title.substring(0, 60)} — ${updateError.message}`)
    } else {
      console.log(`✓ ${course.title.substring(0, 60)}`)
      matched++
    }
  }

  if (unmatched.length) {
    console.log('\nUnmatched courses (need manual questions):')
    unmatched.forEach(t => console.log('  -', t))
  }
  console.log(`\nDone. ${matched}/${courses.length} courses seeded.`)
}

run()
